namespace {
int assertions = 0;
#define CHECK(condition)                                                       \
  do {                                                                         \
    ++assertions;                                                              \
    if (!(condition))                                                          \
      throw std::runtime_error(std::string(#condition) + " at line " +         \
                               std::to_string(__LINE__));                      \
  } while (false)
}  // namespace

extern TFilePath studioRoot;

class TPaletteHandle {
  TPalette *m_palette = nullptr;
  int m_styleIndex = -1, m_styleParamIndex = -1;

public:
  std::function<void()> switched;
  TPalette *getPalette() { return m_palette; }
  int getStyleIndex() { return m_styleIndex; }
  void setPalette(TPalette *palette, int styleIndex = -1);
  void setStyleIndex(int index, bool forceEmit = false);
  void paletteSwitched() {
    if (switched) switched();
  }
  void broadcastColorStyleSwitched() {}
  void notifyPaletteTitleChanged() {}
  void notifyPaletteDirtyFlagChanged() {}
};

struct TXshSimpleLevel {
  int type;
  TPaletteP palette;
  bool readOnly = false, subsequence = false;
  TFilePath path = TFilePath();
  int saves      = 0;
  int getType() { return type; }
  TPalette *getPalette() { return palette.getPointer(); }
  bool isReadOnly() { return readOnly; }
  bool isSubsequence() { return subsequence; }
  TFilePath getPath() { return path; }
  void save(const TFilePath &, const TFilePath &, bool) { ++saves; }
};
struct TXshPaletteLevel {
  TPaletteP palette;
  TPalette *getPalette() { return palette.getPointer(); }
  TFilePath getPath() { return TFilePath("/test/palette.tpl"); }
};
struct TXshLevel {
  TXshSimpleLevel *simple   = nullptr;
  TXshPaletteLevel *palette = nullptr;
  TXshSimpleLevel *getSimpleLevel() { return simple; }
  TXshPaletteLevel *getPaletteLevel() { return palette; }
  int getType() { return simple ? simple->type : PLT_XSHLEVEL; }
  TXshLevel *getSoundLevel() { return this; }
};
struct TXshCell {
  struct {
    TXshLevel *value = nullptr;
    TXshLevel *getPointer() { return value; }
  } m_level;
  bool isEmpty() const { return !m_level.value; }
  TXshSimpleLevel *getSimpleLevel() {
    return m_level.value ? m_level.value->simple : nullptr;
  }
};
struct TXshColumn {
  bool locked = false, visible = true, levelColumn = true, sound = false;
  std::vector<TXshLevel *> m_levels;
  TXshColumn *getSoundColumn() { return sound ? this : nullptr; }
  TXshColumn *getLevelColumn() { return levelColumn ? this : nullptr; }
  bool isLocked() { return locked; }
  bool isCamstandVisible() { return visible; }
};
struct TXsheet {
  TXshColumn column;
  bool columnExists = false;
  std::map<int, TXshCell> cells;
  TXshColumn *getColumn(int index) {
    return index == 0 && columnExists ? &column : nullptr;
  }
  bool isColumnEmpty(int index) { return index != 0 || cells.empty(); }
  TXshCell getCell(int row, int col) {
    return col == 0 && cells.count(row) ? cells.at(row) : TXshCell();
  }
  void getCellRange(int, int &first, int &last) {
    first = cells.empty() ? 0 : cells.begin()->first;
    last  = cells.empty() ? -1 : cells.rbegin()->first;
  }
};
struct Preferences {
  bool autoCreate = true;
  int defaultType = OVL_XSHLEVEL;
  static Preferences *instance() {
    static Preferences value;
    return &value;
  }
  bool isAutoCreateEnabled() { return autoCreate; }
  int getDefLevelType() { return defaultType; }
  bool getBoolValue(int) { return false; }
};
struct FrameHandle {
  int row           = 0;
  bool editingScene = true;
  int getFrame() { return row; }
  bool isEditingScene() { return editingScene; }
};
struct ColumnHandle {
  int col = 0;
  int getColumnIndex() { return col; }
};
struct XsheetHandle {
  TXsheet *xsheet = nullptr;
  TXsheet *getXsheet() { return xsheet; }
  void notifyXsheetSwitched() {}
};
struct LevelHandle {
  TXshLevel *level = nullptr;
  void setLevel(TXshLevel *value) { level = value; }
  TXshLevel *getLevel() { return level; }
  void notifyLevelTitleChange() {}
};
struct SceneHandle {
  ToonzScene *scene = nullptr;
  bool dirty        = false;
  ToonzScene *getScene() { return scene; }
  bool getDirtyFlag() { return dirty; }
  void setDirtyFlag(bool value) { dirty = value; }
  void notifyCastChange() {}
};
struct PaletteController {
  TPaletteHandle level, current, cleanup;
  PaletteController() {
    level.switched = [this] { current.setPalette(level.getPalette()); };
  }
  TPaletteHandle *getCurrentLevelPalette() { return &level; }
  TPaletteHandle *getCurrentPalette() { return &current; }
  void editCleanupPalette() { current.setPalette(cleanup.getPalette()); }
};
struct TApp {
  FrameHandle *m_currentFrame;
  ColumnHandle *m_currentColumn;
  XsheetHandle *m_currentXsheet;
  SceneHandle *m_currentScene;
  LevelHandle *m_currentLevel;
  PaletteController *m_paletteController;
  static TApp *active;
  static TApp *instance() { return active; }
  SceneHandle *getCurrentScene() { return m_currentScene; }
  XsheetHandle *getCurrentXsheet() { return m_currentXsheet; }
  LevelHandle *getCurrentLevel() { return m_currentLevel; }
  TPaletteHandle *getCurrentPalette() {
    return m_paletteController->getCurrentPalette();
  }
  PaletteController *getPaletteController() { return m_paletteController; }
  void updateXshLevel();
};
TApp *TApp::active = nullptr;

struct SaveInProgressGuard {
  static bool available;
  bool acquired() { return available; }
};
