namespace {
struct Fixture {
  QTemporaryDir temporary;
  ToonzScene scene{TFilePath(temporary.path() + "/project-a/palettes")};
  FrameHandle frame;
  ColumnHandle column;
  TXsheet sheet;
  XsheetHandle xsheet{&sheet};
  SceneHandle sceneHandle{&scene};
  LevelHandle level;
  PaletteController palettes;
  TApp app{&frame, &column, &xsheet, &sceneHandle, &level, &palettes};
  FullColorPalette *fc = FullColorPalette::instance();
  Fixture() {
    CHECK(temporary.isValid());
    fc->clear();
    studioRoot               = TFilePath(temporary.path() + "/studio");
    TApp::active             = &app;
    *Preferences::instance() = Preferences();
    DVGui::answer            = 1;
    DVGui::questions = DVGui::errors = 0;
    SceneResources::saveResult = SaveInProgressGuard::available = true;
  }
  ~Fixture() {
    palettes.level.setPalette(nullptr);
    fc->clear();
    TApp::active = nullptr;
  }
  TPalette *palette() { return palettes.level.getPalette(); }
  void update(int row = 0) {
    frame.row = row;
    app.updateXshLevel();
  }
  void edit() {
    update();
    CHECK(palette());
    palette()->getPage(0)->addStyle(TPixel32(21, 43, 65, 255));
    palette()->setCurrentStyleId(2);
    palette()->setDirtyFlag(true);
  }
  void switchScene(ToonzScene &next) {
    // Mirror the explicit detach/clear/new-scene boundary in IoCmd. The
    // complete scene-loading UI is intentionally not simulated here.
    palettes.level.setPalette(nullptr);
    fc->clear();
    sceneHandle.scene = &next;
    sheet.cells.clear();
    update();
  }
};
}  // namespace

int runApplicationTests() {
  int passed = 0, failed = 0;
  auto test = [&](const char *name, const std::function<void()> &body) {
    try {
      body();
      ++passed;
      std::cout << "PASS " << name << std::endl;
    } catch (const std::exception &e) {
      ++failed;
      std::cout << "FAIL " << name << ": " << e.what() << std::endl;
    } catch (...) {
      ++failed;
      std::cout << "FAIL " << name << ": unexpected exception" << std::endl;
    }
  };
  test("edit and retain a selected color before any drawing exists", [] {
    Fixture f;
    f.edit();
    f.update(10);
    CHECK(!f.level.getLevel());
    CHECK(f.sheet.cells.empty());
    CHECK(f.palette()->getStyle(2)->getMainColor() ==
          TPixel32(21, 43, 65, 255));
    CHECK(f.palettes.level.getStyleIndex() == 2);
    CHECK(f.fc->getDirtyFlag());
    Preferences::instance()->autoCreate = false;
    f.update();
    CHECK(!f.palette());
    Preferences::instance()->autoCreate = true;
    f.update();
    CHECK(f.palettes.level.getStyleIndex() == 2);
    CHECK(f.fc->getDirtyFlag());
  });
  test("empty columns respect autocreation and all default level types", [] {
    Fixture f;
    for (int type : {OVL_XSHLEVEL, TZP_XSHLEVEL, PLI_XSHLEVEL}) {
      for (bool enabled : {false, true}) {
        Preferences::instance()->defaultType = type;
        Preferences::instance()->autoCreate  = enabled;
        f.update();
        CHECK(bool(f.palette()) == (type == OVL_XSHLEVEL && enabled));
        CHECK(!f.level.getLevel());
        CHECK(f.sheet.cells.empty());
      }
    }
  });
  test("empty raster columns respect hidden locked and non-level guards", [] {
    Fixture f;
    f.sheet.columnExists  = true;
    f.sheet.column.locked = true;
    f.update();
    CHECK(!f.palette());
    f.sheet.column.locked  = false;
    f.sheet.column.visible = false;
    f.update();
    CHECK(!f.palette());
    f.sheet.column.visible     = true;
    f.sheet.column.levelColumn = false;
    f.update();
    CHECK(!f.palette());
    f.sheet.column.levelColumn = true;
    f.update();
    CHECK(f.palette());
    f.column.col = -1;
    f.update();
    CHECK(!f.palette());
    f.column.col = 0;
    f.update(-1);
    CHECK(!f.palette());
  });
  test("raster gaps follow preceding or first-following level", [] {
    Fixture f;
    TPaletteP p(new TPalette());
    TXshSimpleLevel raster{OVL_XSHLEVEL, p};
    TXshLevel level{&raster};
    f.sheet.cells[10].m_level.value = &level;
    for (int row : {0, 8, 12, 100}) {
      f.update(row);
      CHECK(f.palette() == p.getPointer());
      CHECK(!f.level.getLevel());
    }
    raster.readOnly = true;
    f.update(12);
    CHECK(!f.palette());
    raster.readOnly    = false;
    raster.subsequence = true;
    f.update(12);
    CHECK(!f.palette());
  });
  test("existing indexed levels retain their own palettes and style IDs", [] {
    Fixture f;
    f.edit();
    TPalette *shared = f.palette();
    for (int type : {TZP_XSHLEVEL, PLI_XSHLEVEL}) {
      TPaletteP p(new TPalette());
      p->getPage(0)->addStyle(TPixel32(10, 20, 30, 255));
      p->setCurrentStyleId(2);
      TXshSimpleLevel indexed{type, p};
      TXshLevel level{&indexed};
      f.sheet.cells[10].m_level.value = &level;
      f.update(0);
      CHECK(!f.palette());
      f.update(10);
      CHECK(f.palette() == p.getPointer());
      CHECK(f.level.getLevel() == &level);
      CHECK(f.palettes.level.getStyleIndex() == 2);
      f.update(12);
      CHECK(!f.palette());
      CHECK(p->getStyleCount() == 3);
      CHECK(p->getStyle(2)->getMainColor() == TPixel32(10, 20, 30, 255));
      CHECK(!p->getDirtyFlag());
      CHECK(shared->getStyleCount() == 3);
      f.sheet.cells.clear();
      f.update();
    }
  });
  test("a preceding indexed level is not skipped for a following raster level",
       [] {
         Fixture f;
         TPaletteP inkPalette(new TPalette()), rasterPalette(new TPalette());
         TXshSimpleLevel ink{TZP_XSHLEVEL, inkPalette};
         TXshSimpleLevel raster{OVL_XSHLEVEL, rasterPalette};
         TXshLevel inkLevel{&ink}, rasterLevel{&raster};
         f.sheet.cells[0].m_level.value  = &inkLevel;
         f.sheet.cells[10].m_level.value = &rasterLevel;
         f.update(5);
         CHECK(!f.palette());
         CHECK(!f.level.getLevel());
       });
  test("cleanup palette focus survives early raster palette display", [] {
    Fixture f;
    TPaletteP cleanup(new TPalette());
    cleanup->setIsCleanupPalette(true);
    f.palettes.cleanup.setPalette(cleanup.getPointer());
    f.palettes.editCleanupPalette();
    f.update();
    CHECK(f.palette());
    CHECK(f.palettes.current.getPalette() == cleanup.getPointer());
  });
  test("Save All resource path persists edits with no level", [] {
    Fixture f;
    f.edit();
    CHECK(IoCmd::saveNonSceneFiles());
    CHECK(!f.fc->getDirtyFlag());
    ToonzScene next(f.scene.palettes);
    f.switchScene(next);
    CHECK(f.palette()->getStyleCount() == 3);
    CHECK(f.palette()->getStyle(2)->getMainColor() ==
          TPixel32(21, 43, 65, 255));
    CHECK(!f.level.getLevel());
  });
  test("Save Palette command saves and restores edits before the first drawing",
       [] {
         Fixture f;
         f.edit();
         OverwritePaletteCommandHandler command;
         command.execute();
         CHECK(DVGui::questions == 1);
         CHECK(!f.fc->getDirtyFlag());
         CHECK(!f.level.getLevel());
         ToonzScene next(f.scene.palettes);
         f.switchScene(next);
         CHECK(f.palette()->getStyleCount() == 3);
         CHECK(f.palette()->getStyle(2)->getMainColor() ==
               TPixel32(21, 43, 65, 255));
       });
  test("Save Palette cancellation retains unsaved edits", [] {
    Fixture f;
    f.edit();
    DVGui::answer = 2;
    OverwritePaletteCommandHandler command;
    command.execute();
    CHECK(f.fc->getDirtyFlag());
    CHECK(!TSystem::doesExistFileOrLevel(f.scene.palettes +
                                         "Raster_Drawing_Palette.tpl"));
  });
  test("Save Palette failure preserves edits and reports the error", [] {
    Fixture f;
    f.edit();
    CHECK(QDir().mkpath(f.scene.palettes.getQString() +
                        "/Raster_Drawing_Palette.tpl"));
    OverwritePaletteCommandHandler command;
    command.execute();
    CHECK(f.fc->getDirtyFlag());
    CHECK(DVGui::errors == 1);
  });
  test(
      "Save As Default snapshots early edits without clearing project dirty "
      "state",
      [] {
        Fixture f;
        f.edit();
        SaveAsDefaultRasterPaletteCommandHandler command;
        command.execute();
        CHECK(DVGui::questions == 1);
        CHECK(f.fc->getDirtyFlag());
        CHECK(TSystem::doesExistFileOrLevel(f.fc->getDefaultPalettePath()));
        ToonzScene next(
            TFilePath(f.temporary.path() + "/new-project/palettes"));
        f.switchScene(next);
        CHECK(f.palette()->getStyle(2)->getMainColor() ==
              TPixel32(21, 43, 65, 255));
      });
  test("Save As Default cancellation does not create a default file", [] {
    Fixture f;
    f.edit();
    DVGui::answer = 2;
    SaveAsDefaultRasterPaletteCommandHandler command;
    command.execute();
    CHECK(f.fc->getDirtyFlag());
    CHECK(!TSystem::doesExistFileOrLevel(f.fc->getDefaultPalettePath()));
  });
  test("raster default command refuses indexed and cleanup palettes", [] {
    Fixture f;
    f.edit();
    for (int type : {TZP_XSHLEVEL, PLI_XSHLEVEL}) {
      TPaletteP p(new TPalette());
      TXshSimpleLevel indexed{type, p};
      TXshLevel level{&indexed};
      f.level.setLevel(&level);
      f.palettes.level.setPalette(p.getPointer());
      SaveAsDefaultRasterPaletteCommandHandler command;
      command.execute();
      CHECK(DVGui::questions == 0);
      CHECK(!TSystem::doesExistFileOrLevel(f.fc->getDefaultPalettePath()));
      CHECK(p->getStyleCount() == 2);
    }
    f.level.setLevel(nullptr);
    TPaletteP cleanup(new TPalette());
    cleanup->setIsCleanupPalette(true);
    f.palettes.current.setPalette(cleanup.getPointer());
    SaveAsDefaultRasterPaletteCommandHandler command;
    command.execute();
    CHECK(DVGui::questions == 0);
    CHECK(DVGui::errors == 3);
  });
  test("indexed Save Palette still routes through its existing save mechanism",
       [] {
         Fixture f;
         for (int type : {TZP_XSHLEVEL, PLI_XSHLEVEL}) {
           TPaletteP p(new TPalette());
           p->setDirtyFlag(true);
           TXshSimpleLevel indexed{type, p};
           TXshLevel level{&indexed};
           indexed.path = TFilePath(type == PLI_XSHLEVEL ? "/test/vector.pli"
                                                         : "/test/ink.tlv");
           f.level.setLevel(&level);
           f.palettes.level.setPalette(p.getPointer());
           const int saves = StudioPalette::instance()->saves;
           OverwritePaletteCommandHandler command;
           command.execute();
           CHECK(!p->getDirtyFlag());
           CHECK(indexed.saves == (type == PLI_XSHLEVEL ? 1 : 0));
           CHECK(StudioPalette::instance()->saves ==
                 saves + (type == TZP_XSHLEVEL ? 1 : 0));
           CHECK(!TSystem::doesExistFileOrLevel(f.fc->getDefaultPalettePath()));
         }
         f.level.setLevel(nullptr);
       });
  test("scene and project boundaries reload the appropriate palette", [] {
    Fixture f;
    f.edit();
    CHECK(IoCmd::saveNonSceneFiles());
    f.fc->saveAsDefault(f.palette());
    ToonzScene projectB(TFilePath(f.temporary.path() + "/project-b/palettes"));
    f.switchScene(projectB);
    CHECK(f.palette()->getStyleCount() == 3);
    f.palette()->getStyle(2)->setMainColor(TPixel32(200, 180, 160, 255));
    f.palette()->setDirtyFlag(true);
    CHECK(IoCmd::saveNonSceneFiles());
    ToonzScene projectA(f.scene.palettes);
    f.switchScene(projectA);
    CHECK(f.palette()->getStyle(2)->getMainColor() ==
          TPixel32(21, 43, 65, 255));
    f.switchScene(projectB);
    CHECK(f.palette()->getStyle(2)->getMainColor() ==
          TPixel32(200, 180, 160, 255));
  });
  test("discarding early edits restores the saved project palette", [] {
    Fixture f;
    f.edit();
    CHECK(IoCmd::saveNonSceneFiles());
    f.palette()->getStyle(2)->setMainColor(TPixel32::Red);
    f.palette()->setDirtyFlag(true);
    DVGui::answer = 2;
    CHECK(IoCmd::saveSceneIfNeeded("New Scene"));
    CHECK(DVGui::questions == 1);
    ToonzScene next(f.scene.palettes);
    f.switchScene(next);
    CHECK(f.palette()->getStyle(2)->getMainColor() ==
          TPixel32(21, 43, 65, 255));
  });
  test("cancel preserves early edits and prevents scene clearing", [] {
    Fixture f;
    f.edit();
    DVGui::answer = 3;
    CHECK(!IoCmd::saveSceneIfNeeded("New Scene"));
    CHECK(DVGui::questions == 1);
    CHECK(DVGui::lastQuestion.contains("Raster Drawing Palette.tpl"));
    CHECK(f.scene.clears == 0);
    CHECK(f.fc->getDirtyFlag());
  });
  test("failed palette save blocks the requested scene transition", [] {
    Fixture f;
    f.edit();
    CHECK(QDir().mkpath(f.scene.palettes.getQString() +
                        "/Raster_Drawing_Palette.tpl"));
    CHECK(!IoCmd::saveSceneIfNeeded("Load Scene"));
    CHECK(f.scene.clears == 0);
    CHECK(f.fc->getDirtyFlag());
    CHECK(DVGui::errors == 1);
    CHECK(f.sceneHandle.dirty);
  });
  test("successful prompt save persists palette before scene clearing", [] {
    Fixture f;
    f.edit();
    CHECK(IoCmd::saveSceneIfNeeded("New Scene"));
    CHECK(f.scene.clears == 1);
    CHECK(!f.fc->getDirtyFlag());
    ToonzScene next(f.scene.palettes);
    f.switchScene(next);
    CHECK(f.palette()->getStyleCount() == 3);
  });
  test("resource failures and concurrent saves report failure", [] {
    Fixture f;
    f.edit();
    SceneResources::saveResult = false;
    CHECK(!IoCmd::saveNonSceneFiles());
    CHECK(f.sceneHandle.dirty);
    f.palette()->setDirtyFlag(true);
    SaveInProgressGuard::available = false;
    CHECK(!IoCmd::saveNonSceneFiles());
    CHECK(f.fc->getDirtyFlag());
  });
  std::cout << passed << " application groups passed; " << failed << " failed; "
            << assertions << " assertions" << std::endl;
  return failed;
}
